using FluentValidation;
namespace InventorySystem.API.Middleware;
public class ExceptionMiddleware(RequestDelegate next,ILogger<ExceptionMiddleware> logger){ public async Task InvokeAsync(HttpContext ctx){ try{await next(ctx);} catch(ValidationException ex){ctx.Response.StatusCode=400;await ctx.Response.WriteAsJsonAsync(new{errors=ex.Errors.Select(e=>e.ErrorMessage)});} catch(KeyNotFoundException ex){logger.LogWarning(ex,"Resource not found");ctx.Response.StatusCode=404;await ctx.Response.WriteAsJsonAsync(new{error=ex.Message});} catch(InvalidOperationException ex){logger.LogWarning(ex,"Invalid operation");ctx.Response.StatusCode=400;await ctx.Response.WriteAsJsonAsync(new{error=ex.Message});} catch(Exception ex){logger.LogError(ex,"Unhandled exception");ctx.Response.StatusCode=500;await ctx.Response.WriteAsJsonAsync(new{error="An unexpected error occurred."});} } }
